158	/// Контекст касаний суток: ход монеты — из кэша (`TouchRow::ret_bps`) или из
159	/// реплея (`pre_touch_return_bps_csv` — те же шесть знаков), режим — по
160	/// минуте `start_ms` из `RegimeDay` (нет режима — `None`).
161	pub(crate) fn touch_contexts(
162	    rets: &[[Option<f64>; 3]],
163	    touches: &[TouchRecord],
164	    regime: Option<&RegimeDay>,
165	) -> Vec<TouchContext> {
166	    debug_assert_eq!(rets.len(), touches.len());
167	    touches
168	        .iter()
169	        .zip(rets)
170	        .map(|(t, r)| {
171	            let minute = t.start_ms - t.start_ms.rem_euclid(60_000);
172	            let m = regime
173	                .and_then(|g| g.get(&minute))
174	                .copied()
175	                .unwrap_or([None; 6]);
176	            TouchContext {
177	                axes: [r[0], r[1], r[2], m[0], m[1], m[2], m[3], m[4], m[5]],
178	            }
179	        })
180	        .collect()
181	}
