407	    /// Фильтр набора над касаниями суток с готовым контекстом (`touch_contexts`):
408	    /// контекст подаётся, только если у набора есть ключи контекста.
409	    pub(crate) fn from_set(
410	        set: &FilterSet,
411	        mode: H3Mode,
412	        tick: f64,
413	        lot: f64,
414	        ctx: &'a [TouchContext],
415	    ) -> Self {
416	        Self {
417	            tick,
418	            lot,
419	            frontrun_only: set.frontrun_only,
420	            mode,
421	            min_age_ms: set.min_age_secs.map(|s| s.saturating_mul(1_000)),
422	            min_flow_pct: set.min_flow_pct,
423	            side: set.side.map(Side::from),
424	            eaten_max_pct: set.eaten_max_pct,
425	            eaten_min_pct: set.eaten_min_pct,
426	            frontrun_min_lots: set.frontrun_min_lots,
427	            usd_min: set.usd_min,
428	            ctx: if set.uses_ctx() { Some(ctx) } else { None },
429	            ctx_ranges: set.ctx,
430	        }
431	    }
432	
433	    /// Проходит ли касание `t` с индексом `ti` (индекс — в контекст суток).
434	    #[allow(clippy::cast_precision_loss)]
435	    pub(crate) fn admits(&self, ti: usize, t: &TouchRecord) -> bool {
436	        if self.frontrun_only && t.frontrun_tick.is_none() {
437	            return false;
438	        }
439	        if self.frontrun_min_lots.is_some_and(|n| t.frontrun_lots < n) {
440	            return false;
441	        }
442	        // База E1 (В-66): плотность обязана держать порог при подходе цены,
443	        // а не только при рождении — иначе в сетку идут касания
444	        // «бывших» плотностей. Окно проверено при старте прогона.
445	        if self.mode.holds_at_touch(t) != Some(true) {
446	            return false;
447	        }
448	        if self.min_age_ms.is_some_and(|n| t.age_ms() < n) {
449	            return false;
450	        }
451	        if let Some(s_min) = self.min_flow_pct {
452	            let flow_ok = t.flow_1h_lots > 0
453	                && t.size_at_touch as f64 / t.flow_1h_lots as f64 * 100.0 >= s_min;
454	            if !flow_ok {
455	                return false;
456	            }
457	        }
458	        // Ось стороны: другая сторона выбывает до форм (как возраст и сила).
459	        if self.side.is_some_and(|s| t.side != s) {
460	            return false;
461	        }
462	        // Состояние стены: съедена к касанию сильнее порога — не вход.
463	        if self.eaten_max_pct.is_some_and(|m| eaten_pct(t) > m) {
464	            return false;
465	        }
466	        // T4 (П-02, Г-86): зеркало предыдущей проверки — съедено МЕНЬШЕ
467	        // порога не вход (нужен именно сильно проеденный завал).
468	        if self.eaten_min_pct.is_some_and(|m| eaten_pct(t) < m) {
469	            return false;
470	        }
471	        // Размер стены: номинал при касании ниже порога набора — не вход.
472	        if self.usd_min.is_some_and(|m| {
473	            t.price_tick as f64 * self.tick * t.size_at_touch as f64 * self.lot < m
474	        }) {
475	            return false;
476	        }
477	        // Контекст (S4): ход до касания и режим — вне границ набора или
478	        // без значения при заданной границе — не вход.
479	        if let Some(ctx) = self.ctx {
480	            let c = &ctx[ti];
481	            if !self
482	                .ctx_ranges
483	                .iter()
484	                .zip(&c.axes)
485	                .all(|(r, v)| r.holds(*v))
486	            {
487	                return false;
488	            }
489	        }
490	        true
491	    }
492	}

